import {createContext, useContext} from 'react';
import {useCurrentFrame, useVideoConfig} from 'remotion';

// Generated by scripts/build_timeline.py from the episode config + the real narration take.
export type HighlightTone = 'cyan' | 'coral' | 'amber' | 'cream';
export type TimelineCue = {
  id: string;
  group: string;
  text: string;
  highlight: Array<[string, HighlightTone]>;
  start: number;
  end: number;
  splits?: Array<{text: string; start: number; end: number}>;
};
export type Timeline = {
  episode: string;
  title: string;
  fps: number;
  width: number;
  height: number;
  duration: number;
  durationInFrames: number;
  cues: TimelineCue[];
  events: Record<string, number>;
};

export const TimelineContext = createContext<Timeline | null>(null);

export const useTimeline = () => {
  const tl = useContext(TimelineContext);
  if (!tl) throw new Error('TimelineContext missing');
  return tl;
};

/** Absolute episode time in seconds (components never sit inside offset Sequences). */
export const useTime = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  return frame / fps;
};

export const useEvents = () => useTimeline().events;
